def iterative_optimize(system, optimizer, proof):
    current = proof
    while not system.is_minimal(current):
        current = optimizer.optimize(current)
    return current

def gap_aware_optimize(system, optimizer, proof, min_gap):
    max_steps = system.complexity(proof) // min_gap
    current = proof
    for i in range(max_steps + 1):
        if system.is_minimal(current):
            return i, current
        current = optimizer.optimize(current)
    return max_steps, current

def compose_optimizers(opt1, opt2):
    def composed(proof):
        return opt1.optimize(opt2.optimize(proof))
    return composed
